import { superAdminData } from "./data/user";
import { generateSalt, hashPassword } from "./utils/hash-password";
import { placesData } from "./data/place";
import { PrismaClient, $Enums } from "./generated/prisma";

const prisma = new PrismaClient();

const createSuperAdmin = async () => {
  const salt = generateSalt();
  const hashedPassword = await hashPassword(superAdminData.password, salt);

  let result = await prisma.user.upsert({
    where: {
      username: superAdminData.username,
    },
    create: {
      fullName: superAdminData.fullName,
      hashedPassword,
      salt,
      role: superAdminData.role as $Enums.UserRoleEnum,
      username: superAdminData.username,
    },
    update: {},
  });
};
const createPlaces = async () => {
  for (let i = 0; i < placesData.length; i++)
    await prisma.place.upsert({
      where: {
        title: placesData[i].title,
      },
      create: {
        name: placesData[i].name,
        title: placesData[i].title,
        languageCode: placesData[i].languageCode,
      },
      update: {
        name: placesData[i].name,
        title: placesData[i].title,
        languageCode: placesData[i].languageCode,
      },
    });
};

(async () => {
  try {
    await Promise.all([createSuperAdmin(), createPlaces()]);
    console.log("SEED");
  } catch (error) {
    console.error("Error:", error);
    process.exit(1);
  }
  process.exit(0);
})();
